-- Ṛtam — the Nava Narasimha Kshetra: nine distinct shrines to Narasimha
-- (Vishnu's man-lion avatara) scattered across the forested hills of
-- Ahobilam, Andhra Pradesh — the site where he is held to have slain
-- Hiranyakashipu. Four sit in Upper Ahobilam (Eguva Ahobilam), reached
-- only by a forest trek from the main town; five sit in and around Lower
-- Ahobilam (Diguva Ahobilam), where most pilgrims stay. The existing
-- "Ahobilam Narasimha Temple" entry represents the kshetra's main,
-- easily-accessible shrine and matha seat, and is left untagged here
-- since it does not correspond to one specific numbered form.
--
-- Coordinates: Lower Ahobilam shrines share the town's coordinate (all
-- within a couple of kilometres of it); Upper Ahobilam shrines use an
-- approximation roughly 8km east/upslope, since no source gives a
-- separate precise figure for each individual cave shrine.

insert into public.temples (
  name, deity, sampradaya, significance, country, state, district, town, latitude, longitude, sandhya_friendly, sandhya_notes, samidhadhanam_friendly, samidhadhanam_notes, food_tier, food_source_name, food_distance_km, nearest_river_name, river_distance_km, best_season_notes, sthala_purana, sthala_purana_source, architecture_style, construction_century, status
) values
(
  'Ahobila Narasimha Temple, Upper Ahobilam', 'Ahobila Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.135, 78.79, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.5, 'Oct–Feb; the forest trek to Upper Ahobilam is best avoided in peak summer or heavy monsoon.', 'The principal and most ancient of the Nava Narasimha, also called Ugra Narasimha — the fierce form in which Vishnu tore apart Hiranyakashipu. The sanctum is a low, naturally occurring cave in the hillside, with a swayambhu (self-manifested) image.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Kroda Narasimha Temple, Upper Ahobilam', 'Kroda Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.135, 78.79, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.5, 'Oct–Feb; the forest trek to Upper Ahobilam is best avoided in peak summer or heavy monsoon.', 'One of the Nava Narasimha, worshipped here in a boar-faced form (sometimes called Varaha Narasimha), blending Vishnu''s Varaha and Narasimha avataras. A separate Lakshmi Narasimha image also has darshan at the same shrine.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Malola Narasimha Temple, Upper Ahobilam', 'Malola Narasimha (Vishnu) / Lakshmi', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.135, 78.79, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.5, 'Oct–Feb; the forest trek to Upper Ahobilam is best avoided in peak summer or heavy monsoon.', 'One of the Nava Narasimha and, uniquely, its most peaceful form — the name combines "Ma" (Mother Lakshmi) and "lola" (beloved), since Lakshmi is seated on the Lord''s lap here. This form is also the traveling utsava (festival) deity of the Ahobila Matha''s pontiffs.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Jwala Narasimha Temple, Upper Ahobilam', 'Jwala Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.135, 78.79, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.5, 'Oct–Feb; the forest trek to Upper Ahobilam is best avoided in peak summer or heavy monsoon.', 'One of the Nava Narasimha, marking the exact spot tradition holds Narasimha tore apart the demon king Hiranyakashipu with his claws. The nearby Rakta Kunda ("blood pool") is said to still carry a reddish tinge from where the Lord washed his hands afterward. Two further forms, Sthanu Narasimha (emerging from a pillar) and Veera Narasimha (in battle), are also enshrined here.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Yogananda Narasimha Temple, Lower Ahobilam', 'Yogananda Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.1333, 78.7167, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.3, 'Oct–Feb.', 'One of the Nava Narasimha, depicted seated in a yogic posture with binding straps (yoga-patta), said to represent Narasimha teaching the young devotee Prahlada the practice of yoga after Hiranyakashipu''s defeat.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Chatravata Narasimha Temple, Lower Ahobilam', 'Chatravata Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.1333, 78.7167, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.3, 'Oct–Feb.', 'One of the Nava Narasimha, worshipped beneath a peepal tree amid thorny scrub, with a serene, smiling countenance and the left hand held in tala mudra.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Pavana Narasimha Temple, Lower Ahobilam', 'Pavana Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.1333, 78.7167, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Pavana', 0.2, 'Oct–Feb.', 'One of the Nava Narasimha and reckoned the most tranquil of the nine forms, set on the banks of the Pavana stream.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Bhargava Narasimha Temple, Lower Ahobilam', 'Bhargava Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.1333, 78.7167, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.4, 'Oct–Feb.', 'One of the Nava Narasimha and among its most fierce forms, set on the banks of the Akshaya Tirtha tank where the sage Parashurama (Bhargava) is said to have performed his ablutions and worship.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
),
(
  'Karanja Narasimha Temple, Lower Ahobilam', 'Karanja Narasimha (Vishnu)', 'Vaishnava', array['Nava Narasimha'], 'India', 'Andhra Pradesh', 'Nandyal', 'Ahobilam', 15.1333, 78.7167, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Bhavanasini', 0.4, 'Oct–Feb.', 'One of the Nava Narasimha, also called Saranga Narasimha, depicted standing beneath a karanja (honge) tree and holding the Saranga bow.', 'Local/regional tradition (Nava Narasimha Kshetra)', null, null, 'approved'
);

